4097	// ---------------------------------------------------------------------------
4098	// 离线响应分支可达性诊断（reach 子命令）
4099	// ---------------------------------------------------------------------------
4100	//
4101	// 读取一份通过与 serve 完全相同严格校验的场景配置与一个 POST 接口的字面路径，
4102	// 离线诊断该接口 branches 中每一分支及兜底 responses 是否可达：
4103	//   reachable      —— 存在通过正文检查的请求正文，且该正文首先命中此支；
4104	//   covered        —— 存在满足此支条件的合格正文，但它们全部首先命中前序分支
4105	//                      （遮挡按前序分支的命中并集判定，不是单支包含，也不抽样）；
4106	//   contradictory  —— 条件与正文规则矛盾，不存在满足条件的合格正文。
4107	// 不监听、不发送请求、不修改任何文件。可达分支/兜底各给一份完整请求样例
4108	// （方法、路径、必要头、原始 JSON 正文，补全全部必填字段），样例须通过正文
4109	// 检查并实际选中所报分支或兜底。
4110	//
4111	// 诊断范围（超出即整份拒绝，退出 2）：
4112	// - 接口必须是 POST、声明了非空 branches；
4113	// - 根 requestBody 必须是 object（可附 nullable）；
4114	// - 每个 when 指针必须是**单段** RFC 6901 指针，指向根对象**已声明的标量字段**
4115	//   （根指针 ""、多段指针、未声明字段、object/array 字段均拒绝）；其余字段仍
4116	//   完全按现有递归规则参与“合格正文”的构造与判定。空字段名、__proto__、
4117	//   ~0/~1 转义按原语义处理。
4118	//
4119	// 判定精确依据现有 type/enum/nullable/必填可选/额外字段语义：缺失与 null 分开、
4120	// 0 与 -0 等价、不转换类型；根可空时 JSON null 也参与兜底可达性判断。
4121	
4122	class ReachError extends Error {
4123	  constructor(message: string) {
4124	    super(message);
4125	    this.name = 'ReachError';
4126	  }
4127	}
4128	
4129	type BranchReachStatus = 'reachable' | 'covered' | 'contradictory';
4130	
4131	interface ReachExample {
4132	  readonly method: 'POST';
4133	  readonly path: string;
4134	  readonly headers: { readonly 'Content-Type': 'application/json' };
4135	  readonly body: string;
4136	}
4137	
4138	interface ReachReason {
4139	  readonly pointer: string;
4140	  readonly message: string;
4141	}
4142	
4143	interface BranchReach {
4144	  readonly id: string;
4145	  readonly status: BranchReachStatus;
4146	  readonly example?: ReachExample;
4147	  // covered：共同遮挡此支的前序分支标识（不必最小）
4148	  readonly coveredBy?: readonly string[];
4149	  readonly message?: string;
4150	  // contradictory：定位到具体条件指针的矛盾原因（可多条）
4151	  readonly reasons?: readonly ReachReason[];
4152	}
4153	
4154	interface FallbackReach {
4155	  readonly status: 'reachable' | 'covered';
4156	  readonly example?: ReachExample;
4157	  readonly coveredBy?: readonly string[];
4158	  readonly message?: string;
4159	}
4160	
4161	interface ReachReport {
4162	  readonly configFile: string;
4163	  readonly method: 'POST';
4164	  readonly path: string;
4165	  readonly branches: readonly BranchReach[];
4166	  readonly fallback: FallbackReach;
4167	  readonly unreachableBranches: number;
4168	}
4169	
4170	// 找不到见证正文的哨兵：不能用 null——根可空时 JSON null 本身就是合法见证
4171	const NO_WITNESS: unique symbol = Symbol('reach-no-witness');
4172	type Witness = unknown | typeof NO_WITNESS;
4173	
4174	// 标量条件的非 null 值是否满足字段标量规则的“类型”部分（不做类型转换）
4175	function scalarTypeConforms(
4176	  rule: Extract<BodyRule, { kind: ScalarKind }>,
4177	  value: string | number | boolean,
4178	): boolean {
4179	  switch (rule.kind) {
4180	    case 'string':
4181	      return typeof value === 'string';
4182	    case 'boolean':
4183	      return typeof value === 'boolean';
4184	    case 'number':
4185	      return typeof value === 'number' && Number.isFinite(value);
4186	    case 'integer':
4187	      return Number.isInteger(value);
4188	    case 'null':
4189	      return false;
4190	  }
4191	}
4192	
4193	// 条件值与标量字段规则的矛盾原因；无矛盾返回 null。
4194	// 严格按现有语义：类型不符只报类型；类型相符但不在枚举报枚举；
4195	// null 仅当规则接受 null（nullable 且枚举含 null，或 type:"null"）才可行。
4196	function scalarConditionConflict(
4197	  rule: Extract<BodyRule, { kind: ScalarKind }>,
4198	  value: BranchConditionValue,
4199	): { kind: 'type' | 'enum' | 'null' } | null {
4200	  if (value === null) {
4201	    return ruleAcceptsNullValue(rule) ? null : { kind: 'null' };
4202	  }
4203	  if (!scalarTypeConforms(rule, value)) {
4204	    return { kind: 'type' };
4205	  }
4206	  if (rule.enum !== undefined && !rule.enum.includes(value as EnumValue)) {
4207	    return { kind: 'enum' };
4208	  }
4209	  return null;
4210	}
4211	
4212	// 字段某一取值维度上的代表值。等值条件只能区分“指针处是否严格等于某常量”，
4213	// 故只需：各分支引用过的合格常量、null（若规则接受），以及一个与所有被引用
4214	// 常量都不同的合格“其余值”（枚举取未被引用的候选；无枚举时构造）。
4215	// 任意两个未被引用的合格值对全部条件不可区分，因此该有限域精确，不是抽样。
4216	function freshScalarValue(
4217	  rule: Extract<BodyRule, { kind: ScalarKind }>,
4218	  referenced: ReadonlySet<unknown>,
4219	): unknown {
4220	  if (rule.enum !== undefined) {
4221	    return rule.enum.find((candidate) => candidate !== null && !referenced.has(candidate));
4222	  }
4223	  if (rule.kind === 'boolean') {
4224	    return !referenced.has(false) ? false : !referenced.has(true) ? true : undefined;
4225	  }
4226	  if (rule.kind === 'null') {
4227	    return undefined;
4228	  }
4229	  if (rule.kind === 'string') {
4230	    for (let i = 0; ; i += 1) {
4231	      const candidate = i === 0 ? 'contractlab' : `contractlab_${i}`;
4232	      if (!referenced.has(candidate)) {
4233	        return candidate;
4234	      }
4235	    }
4236	  }
4237	  // number / integer：取未被引用的最小非负整数（integer 合法；number 也合法）
4238	  for (let i = 0; ; i += 1) {
4239	    if (!referenced.has(i)) {
4240	      return i;
4241	    }
4242	  }
4243	}
4244	
4245	interface ReachDim {
4246	  readonly name: string;
4247	  // 该字段“存在”时的代表值（必非空：标量规则总有至少一个接受值）
4248	  readonly values: readonly unknown[];
4249	  // 规则未标必填时字段还可以缺失；缺失与显式 null 是不同的维度取值
4250	  readonly optional: boolean;
4251	}
4252	
4253	// 单支的条件分析：与字段规则一致时给出 字段名 -> 条件常量 的固定取值
4254	// （一支的全部条件都是“某标量字段等于某常量”）；矛盾时给出定位原因。
4255	interface BranchAnalysis {
4256	  readonly ok: boolean;
4257	  readonly pins?: ReadonlyMap<string, BranchConditionValue>;
4258	  readonly reasons?: readonly ReachReason[];
4259	}
4260	
4261	function analyzeBranchConditions(
4262	  branch: BranchSpec,
4263	  rootFields: ReadonlyMap<string, FieldRule>,
4264	): BranchAnalysis {
4265	  const pins = new Map<string, BranchConditionValue>();
4266	  const grouped = new Map<string, BranchConditionValue[]>();
4267	  for (const condition of branch.conditions) {
4268	    const name = condition.segments[0];
4269	    const list = grouped.get(name);
4270	    if (list === undefined) {
4271	      grouped.set(name, [condition.value]);
4272	    } else {
4273	      list.push(condition.value);
4274	    }
4275	  }
4276	
4277	  const reasons: ReachReason[] = [];
4278	  for (const [name, values] of grouped) {
4279	    const pointer = `/${escapePointerSegment(name)}`;
4280	    // 范围预检已保证字段存在且为标量规则
4281	    const scalarRule = (rootFields.get(name) as FieldRule).rule as Extract<BodyRule, { kind: ScalarKind }>;
4282	
4283	    // 同一指针上的多个常量必须两两严格相等（0 与 -0 视为相等）；
4284	    // null 与任何非 null 值互不相容。
4285	    const distinct: BranchConditionValue[] = [];
4286	    for (const v of values) {
4287	      if (!distinct.some((d) => d === v)) {
4288	        distinct.push(v);
4289	      }
4290	    }
4291	    if (distinct.length > 1) {
4292	      reasons.push({
4293	        pointer,
4294	        message: `同一指针上的等值条件值 ${JSON.stringify(distinct)} 互不相容（严格相等、不做类型转换），没有正文能同时满足`,
4295	      });
4296	      continue;
4297	    }
4298	
4299	    const value = distinct[0];
4300	    const conflict = scalarConditionConflict(scalarRule, value);
4301	    if (conflict === null) {
4302	      pins.set(name, value);
4303	      continue;
4304	    }
4305	    if (conflict.kind === 'type') {
4306	      reasons.push({
4307	        pointer,
4308	        message: `条件值 ${JSON.stringify(value)} 与该字段的 ${scalarRule.kind} 规则矛盾（不做类型转换），不存在在此指针处等于该值的合格正文`,
4309	      });
4310	    } else if (conflict.kind === 'enum') {
4311	      reasons.push({
4312	        pointer,
4313	        message: `条件值 ${JSON.stringify(value)} 不在该字段枚举 ${JSON.stringify(scalarRule.enum)} 之中，不存在在此指针处等于该值的合格正文`,
4314	      });
4315	    } else {
4316	      reasons.push({
4317	        pointer,
4318	        message: '条件要求该字段为 JSON null，但字段规则不接受 null；字段缺失也不等于显式 null，不存在满足该条件的合格正文',
4319	      });
4320	    }
4321	  }
4322	
4323	  return reasons.length === 0 ? { ok: true, pins } : { ok: false, reasons };
4324	}
