4326	// 在根对象规则与全部分支条件之上做精确的有限域可达性求解。
4327	class ReachSolver {
4328	  private readonly dims: readonly ReachDim[];
4329	  private readonly rootRule: Extract<BodyRule, { kind: 'object' }>;
4330	  private readonly branches: readonly BranchSpec[];
4331	
4332	  constructor(
4333	    rootRule: Extract<BodyRule, { kind: 'object' }>,
4334	    branches: readonly BranchSpec[],
4335	  ) {
4336	    this.rootRule = rootRule;
4337	    this.branches = branches;
4338	    this.dims = this.buildDims();
4339	  }
4340	
4341	  private buildDims(): ReachDim[] {
4342	    // 字段首次被任何分支引用的顺序（配置顺序）
4343	    const names: string[] = [];
4344	    const referenced = new Map<string, Set<unknown>>();
4345	    for (const branch of this.branches) {
4346	      for (const condition of branch.conditions) {
4347	        const name = condition.segments[0];
4348	        if (!referenced.has(name)) {
4349	          referenced.set(name, new Set<unknown>());
4350	          names.push(name);
4351	        }
4352	      }
4353	    }
4354	
4355	    const dims: ReachDim[] = [];
4356	    for (const name of names) {
4357	      const field = this.rootRule.fields.get(name) as FieldRule;
4358	      const scalarRule = field.rule as Extract<BodyRule, { kind: ScalarKind }>;
4359	      const ref = referenced.get(name) as Set<unknown>;
4360	      const values: unknown[] = [];
4361	      const seen = new Set<unknown>();
4362	      const push = (v: unknown): void => {
4363	        if (v !== undefined && !seen.has(v)) {
4364	          seen.add(v);
4365	          values.push(v);
4366	        }
4367	      };
4368	      // 各分支引用过且合格的常量
4369	      for (const branch of this.branches) {
4370	        for (const condition of branch.conditions) {
4371	          if (condition.segments[0] !== name) {
4372	            continue;
4373	          }
4374	          if (scalarConditionConflict(scalarRule, condition.value) === null) {
4375	            push(condition.value);
4376	            ref.add(condition.value);
4377	          }
4378	        }
4379	      }
4380	      // null（与“缺失”不同的显式取值）
4381	      if (ruleAcceptsNullValue(scalarRule)) {
4382	        push(null);
4383	      }
4384	      // 一个与全部被引用常量都不同的合格值；没有时（如枚举候选已被全部引用）省略
4385	      push(freshScalarValue(scalarRule, ref));
4386	      dims.push({ name, values, optional: !field.required });
4387	    }
4388	    return dims;
4389	  }
4390	
4391	  // 一支条件是否被正文全部满足：取不到值（缺失/无法遍历）即不匹配；
4392	  // 严格相等、不做类型转换（resolvePointer 视空字段名与 __proto__ 为普通字段）
4393	  private satisfies(conditions: readonly BranchCondition[], value: unknown): boolean {
4394	    for (const condition of conditions) {
4395	      const actual = resolvePointer(value, condition.segments);
4396	      if (actual === undefined || actual !== condition.value) {
4397	        return false;
4398	      }
4399	    }
4400	    return true;
4401	  }
4402	
4403	  private firstMatch(value: unknown): number | null {
4404	    for (let i = 0; i < this.branches.length; i += 1) {
4405	      if (this.satisfies(this.branches[i].conditions, value)) {
4406	        return i;
4407	      }
4408	    }
4409	    return null;
4410	  }
4411	
4412	  // 从必填字段最小样本开始构造根对象（字段名含空名/__proto__ 时用无原型对象）
4413	  private baseObject(): Record<string, unknown> {
4414	    const obj: Record<string, unknown> = Object.create(null);
4415	    for (const [name, field] of this.rootRule.fields) {
4416	      if (field.required) {
4417	        obj[name] = sampleValue(field.rule);
4418	      }
4419	    }
4420	    return obj;
4421	  }
4422	
4423	  // 按维度递归枚举合格正文，返回第一个让 predicate 成立的值；全部不成立返回 NO_WITNESS。
4424	  // pins 固定某些字段（某支的等值条件），其余维度取代表值——域对等值条件精确。
4425	  private findObject(
4426	    pins: ReadonlyMap<string, BranchConditionValue>,
4427	    predicate: (value: unknown) => boolean,
4428	  ): Record<string, unknown> | typeof NO_WITNESS {
4429	    const dims = this.dims.filter((dim) => !pins.has(dim.name));
4430	    const base = this.baseObject();
4431	    for (const [name, value] of pins) {
4432	      base[name] = value;
4433	    }
4434	
4435	    const problems: StructureProblem[] = [];
4436	    const visit = (index: number): Record<string, unknown> | typeof NO_WITNESS => {
4437	      if (index === dims.length) {
4438	        problems.length = 0;
4439	        checkRule(this.rootRule, base, '', problems);
4440	        if (problems.length === 0 && predicate(base)) {
4441	          return base;
4442	        }
4443	        return NO_WITNESS;
4444	      }
4445	      const dim = dims[index];
4446	      if (dim.optional) {
4447	        // 可选字段先尝试缺失（缺失与显式 null 分开）
4448	        delete base[dim.name];
4449	        const found = visit(index + 1);
4450	        if (found !== NO_WITNESS) {
4451	          return found;
4452	        }
4453	      }
4454	      for (const value of dim.values) {
4455	        base[dim.name] = value;
4456	        const found = visit(index + 1);
4457	        if (found !== NO_WITNESS) {
4458	          return found;
4459	        }
4460	      }
4461	      return NO_WITNESS;
4462	    };
4463	    return visit(0);
4464	  }
4465	
4466	  // 找一份合格正文：根可空时先尝试 JSON null（分支字段指针在 null 上取不到值，
4467	  // 任何分支都不命中 null），再在对象域上求解；pins 非空时只能是对象正文。
4468	  // 找到返回该 JSON 值（可能就是 null），找不到返回 NO_WITNESS。
4469	  findWitness(
4470	    pins: ReadonlyMap<string, BranchConditionValue>,
4471	    predicate: (value: unknown) => boolean,
4472	  ): Witness {
4473	    if (pins.size === 0 && ruleAcceptsNullValue(this.rootRule)) {
4474	      if (predicate(null)) {
4475	        return null;
4476	      }
4477	    }
4478	    const obj = this.findObject(pins, predicate);
4479	    return obj;
4480	  }
4481	
4482	  // 合并两支的固定取值；同名字段常量不同（严格相等）则不存在共同正文
4483	  private mergePins(
4484	    a: ReadonlyMap<string, BranchConditionValue>,
4485	    b: ReadonlyMap<string, BranchConditionValue>,
4486	  ): Map<string, BranchConditionValue> | null {
4487	    const merged = new Map(a);
4488	    for (const [name, value] of b) {
4489	      const existing = merged.get(name);
4490	      if (existing !== undefined && existing !== value) {
4491	        return null;
4492	      }
4493	      merged.set(name, value);
4494	    }
4495	    return merged;
4496	  }
4497	
4498	  private example(value: unknown, routePath: string): ReachExample {
4499	    return {
4500	      method: 'POST',
4501	      path: routePath,
4502	      headers: { 'Content-Type': 'application/json' },
4503	      body: JSON.stringify(value),
4504	    };
4505	  }
4506	
4507	  solve(routePath: string): { branches: BranchReach[]; fallback: FallbackReach } {
4508	    const analyses = this.branches.map((branch) => analyzeBranchConditions(branch, this.rootRule.fields));
4509	
4510	    const branchResults: BranchReach[] = [];
4511	    for (let i = 0; i < this.branches.length; i += 1) {
4512	      const branch = this.branches[i];
4513	      const analysis = analyses[i];
4514	      if (!analysis.ok || analysis.pins === undefined) {
4515	        branchResults.push({ id: branch.id, status: 'contradictory', reasons: analysis.reasons });
4516	        continue;
4517	      }
4518	
4519	      // 存在合格正文首先命中此支？
4520	      const direct = this.findWitness(analysis.pins, (value) => this.firstMatch(value) === i);
4521	      if (direct !== NO_WITNESS) {
4522	        branchResults.push({ id: branch.id, status: 'reachable', example: this.example(direct, routePath) });
4523	        continue;
4524	      }
4525	
4526	      // 满足此支的合格正文必然首先命中某些前序分支——逐支给出共同遮挡者
4527	      const coveredBy: string[] = [];
4528	      for (let j = 0; j < i; j += 1) {
4529	        const prior = analyses[j];
4530	        if (!prior.ok || prior.pins === undefined) {
4531	          continue;
4532	        }
4533	        const merged = this.mergePins(analysis.pins, prior.pins);
4534	        if (merged === null) {
4535	          continue;
4536	        }
4537	        // 同时满足 i 与 j、且 j 之前所有分支都不命中的合格正文
4538	        const witness = this.findWitness(merged, (value) => this.firstMatch(value) === j);
4539	        if (witness !== NO_WITNESS) {
4540	          coveredBy.push(this.branches[j].id);
4541	        }
4542	      }
4543	      branchResults.push({
4544	        id: branch.id,
4545	        status: 'covered',
4546	        coveredBy,
4547	        message:
4548	          `存在满足本支全部条件的合格正文，但它们首先命中的都是前序分支；` +
4549	          `前序分支 ${JSON.stringify(coveredBy)} 的命中区域并集已覆盖本支，本支永远不会被首先选中`,
4550	      });
4551	    }
4552	
4553	    // 兜底：存在任何分支都不命中的合格正文（含根为 JSON null）即可达
4554	    const fallbackBody = this.findWitness(new Map(), (value) => this.firstMatch(value) === null);
4555	    let fallback: FallbackReach;
4556	    if (fallbackBody !== NO_WITNESS) {
4557	      fallback = { status: 'reachable', example: this.example(fallbackBody, routePath) };
4558	    } else {
4559	      const coveredBy = this.branches
4560	        .map((branch, j) => {
4561	          const analysis = analyses[j];
4562	          if (!analysis.ok || analysis.pins === undefined) {
4563	            return NO_WITNESS;
4564	          }
4565	          const witness = this.findWitness(analysis.pins, (value) => this.firstMatch(value) === j);
4566	          return witness !== NO_WITNESS ? branch.id : NO_WITNESS;
4567	        })
4568	        .filter((id): id is string => id !== NO_WITNESS);
4569	      fallback = {
4570	        status: 'covered',
4571	        coveredBy,
4572	        message:
4573	          `没有任何合格正文落到兜底：全部合格正文都被分支 ${JSON.stringify(coveredBy)} 的命中区域并集覆盖`,
4574	      };
4575	    }
4576	
4577	    return { branches: branchResults, fallback };
4578	  }
4579	}
