4645	async function runReach(configArg: string, pathArg: string): Promise<never> {
4646	  const configFile = path.resolve(configArg);
4647	
4648	  let specs: EndpointSpec[];
4649	  try {
4650	    specs = await loadSpecsFromFile(configFile);
4651	  } catch (e) {
4652	    process.stderr.write(`${APP_NAME}: reach 场景配置：${describeError(e)}\n`);
