4673	      process.exit(2);
4674	    }
4675	    process.stderr.write(`${APP_NAME}: reach 失败：${describeError(e)}\n`);
4676	    process.exit(2);
4677	  }
4678	
4679	  process.stdout.write(`${JSON.stringify(report, null, 2)}\n`);
4680	  // 有不可达分支退出 1；兜底不可达仅作信息，不改变退出码
4681	  process.exit(report.unreachableBranches > 0 ? 1 : 0);
4682	}
