// 标量条件的非 null 值是否满足字段标量规则的“类型”部分（不做类型转换）
function scalarTypeConforms(
  rule: Extract<BodyRule, { kind: ScalarKind }>,
  value: string | number | boolean,
): boolean {
  switch (rule.kind) {
    case 'string':
      return typeof value === 'string';
    case 'boolean':
      return typeof value === 'boolean';
    case 'number':
      return typeof value === 'number' && Number.isFinite(value);
    case 'integer':
      return Number.isInteger(value);
    case 'null':
      return false;
  }
}

// 条件值与标量字段规则的矛盾原因；无矛盾返回 null。
// 严格按现有语义：类型不符只报类型；类型相符但不在枚举报枚举；
// null 仅当规则接受 null（nullable 且枚举含 null，或 type:"null"）才可行。
function scalarConditionConflict(
  rule: Extract<BodyRule, { kind: ScalarKind }>,
  value: BranchConditionValue,
): { kind: 'type' | 'enum' | 'null' } | null {
  if (value === null) {
    return ruleAcceptsNullValue(rule) ? null : { kind: 'null' };
  }
  if (!scalarTypeConforms(rule, value)) {
    return { kind: 'type' };
  }
  if (rule.enum !== undefined && !rule.enum.includes(value as EnumValue)) {
    return { kind: 'enum' };
  }
  return null;
}

// 标量维度的一个与全部被引用常量都不同的合格“其余值”（枚举取未被引用候选；
// 无枚举时构造）。任意两个未被引用的合格值对全部等值条件不可区分，故该代表
// 值与缺失、null 一起构成精确有限域，不是抽样；没有合格其余值时省略。
function freshScalarValue(
  rule: Extract<BodyRule, { kind: ScalarKind }>,
  referenced: ReadonlySet<unknown>,
): unknown {
  if (rule.enum !== undefined) {
    return rule.enum.find((candidate) => candidate !== null && !referenced.has(candidate));
  }
  if (rule.kind === 'boolean') {
    return !referenced.has(false) ? false : !referenced.has(true) ? true : undefined;
  }
  if (rule.kind === 'null') {
    return undefined;
  }
  if (rule.kind === 'string') {
    for (let i = 0; ; i += 1) {
      const candidate = i === 0 ? 'contractlab' : `contractlab_${i}`;
      if (!referenced.has(candidate)) {
        return candidate;
      }
    }
  }
  // number / integer：取未被引用的最小非负整数（integer 合法；number 也合法）
  for (let i = 0; ; i += 1) {
    if (!referenced.has(i)) {
      return i;
    }
  }
}

// 条件在约束树中的定位（树节点见 ReachNode）。
interface ReachConditionRef {
  readonly branchId: string;
  // 原始 RFC 6901 指针（报告与定位用）
  readonly pointer: string;
  // 已解码指针段
  readonly segments: readonly string[];
  readonly value: BranchConditionValue;
}

// 约束树节点：根对象或某个被条件经多段指针穿过的中间 object 字段。
// 共享祖先的全部条件（同一对象上的字段指针）汇聚到同一节点，
// 例如 /buyer/state 与 /buyer/flag 的 buyer 是同一节点。
class ReachNode {
  readonly objectRule: Extract<BodyRule, { kind: 'object' }>;
  // 本对象上被条件直接引用的标量子字段名 -> 该字段的标量规则
  readonly scalarFields = new Map<string, Extract<BodyRule, { kind: ScalarKind }>>();
  // 本对象上被条件穿过的 object 子字段名 -> 子节点
  readonly children = new Map<string, ReachNode>();
  // 子字段是否必填（object 与标量子字段都登记；缺失与显式 null 据此区分）
  readonly requiredNames = new Set<string>();

  constructor(objectRule: Extract<BodyRule, { kind: 'object' }>) {
    this.objectRule = objectRule;
  }
}

// 一支的条件分析：无矛盾时给出钉值表（条件 -> 常量），并登记各条件所在节点；
// 矛盾时给出按完整 RFC 6901 指针定位的原因。
interface BranchAnalysis {
  readonly ok: boolean;
  // 条件引用 -> 钉住的常量（仅含与规则一致的条件）
  readonly pins?: ReadonlyMap<ReachConditionRef, BranchConditionValue>;
  readonly reasons?: readonly ReachReason[];
}

// 同一标量维度上的多个条件常量必须两两严格相等（0 与 -0 视为相等）。
function distinctConstants(values: readonly BranchConditionValue[]): BranchConditionValue[] {
  const distinct: BranchConditionValue[] = [];
  for (const v of values) {
    if (!distinct.some((d) => d === v)) {
      distinct.push(v);
    }
  }
  return distinct;
}

function analyzeBranchConditions(
  branch: BranchSpec,
  rootNode: ReachNode,
): BranchAnalysis {
  // 以“所在节点 + 字段名”为标量维度，聚合一支在同一维度上的全部常量
  const dims = new Map<ReachNode, Map<string, BranchConditionValue[]>>();
  const conditionRefs: ReachConditionRef[] = [];
  for (const condition of branch.conditions) {
    const ref: ReachConditionRef = {
      branchId: branch.id,
      pointer: condition.pointer,
      segments: condition.segments,
      value: condition.value,
    };
    conditionRefs.push(ref);
    // 范围预检保证：至少一段、沿对象字段链可走、终点标量
    let node = rootNode;
    for (let k = 0; k < condition.segments.length - 1; k += 1) {
      node = node.children.get(condition.segments[k]) as ReachNode;
    }
    const leafName = condition.segments[condition.segments.length - 1];
    let byName = dims.get(node);
    if (byName === undefined) {
      byName = new Map<string, BranchConditionValue[]>();
      dims.set(node, byName);
    }
    const list = byName.get(leafName);
    if (list === undefined) {
      byName.set(leafName, [condition.value]);
    } else {
      list.push(condition.value);
    }
  }

  const reasons: ReachReason[] = [];
  const pins = new Map<ReachConditionRef, BranchConditionValue>();
  for (const [node, byName] of dims) {
    for (const [name, values] of byName) {
      // 条件原始指针：以节点所在深度与字段名重建（各条件段解码前转义回去）
      const pointerFor = (ref: ReachConditionRef): string =>
        `/${ref.segments.map(escapePointerSegment).join('/')}`;
      const scalarRule = node.scalarFields.get(name) as Extract<BodyRule, { kind: ScalarKind }>;

      const distinct = distinctConstants(values);
      if (distinct.length > 1) {
        reasons.push({
          pointer: pointerFor(conditionRefs.find(
            (r) => r.segments[r.segments.length - 1] === name &&
              thisNodeOf(r, rootNode) === node,
          ) as ReachConditionRef),
          message: `同一指针上的等值条件值 ${JSON.stringify(distinct)} 互不相容（严格相等、不做类型转换），没有正文能同时满足`,
        });
        continue;
      }

      const value = distinct[0];
      const conflict = scalarConditionConflict(scalarRule, value);
      const anyRef = conditionRefs.find(
        (r) => r.segments[r.segments.length - 1] === name && thisNodeOf(r, rootNode) === node,
      ) as ReachConditionRef;
      if (conflict === null) {
        for (const ref of conditionRefs) {
          if (ref.segments[ref.segments.length - 1] === name && thisNodeOf(ref, rootNode) === node) {
            pins.set(ref, value);
          }
        }
        continue;
      }
      if (conflict.kind === 'type') {
        reasons.push({
          pointer: pointerFor(anyRef),
          message: `条件值 ${JSON.stringify(value)} 与该字段的 ${scalarRule.kind} 规则矛盾（不做类型转换），不存在在此指针处等于该值的合格正文`,
        });
      } else if (conflict.kind === 'enum') {
        reasons.push({
          pointer: pointerFor(anyRef),
          message: `条件值 ${JSON.stringify(value)} 不在该字段枚举 ${JSON.stringify(scalarRule.enum)} 之中，不存在在此指针处等于该值的合格正文`,
        });
      } else {
        reasons.push({
          pointer: pointerFor(anyRef),
          message: '条件要求该字段为 JSON null，但字段规则不接受 null；字段缺失也不等于显式 null，不存在满足该条件的合格正文',
        });
      }
    }
  }

  return reasons.length === 0 ? { ok: true, pins } : { ok: false, reasons };
}

// 取条件终点所在的约束节点（与 analyzeBranchConditions 中的遍历一致）
function thisNodeOf(ref: ReachConditionRef, rootNode: ReachNode): ReachNode {
  let node = rootNode;
  for (let k = 0; k < ref.segments.length - 1; k += 1) {
    node = node.children.get(ref.segments[k]) as ReachNode;
  }
  return node;
}

// 标量维度：该字段在其所属对象上的取值域。
interface ReachDim {
  readonly node: ReachNode;
  readonly name: string;
  // 字段“存在且非 null”时的代表值（钉值除外，钉值在枚举时单独注入）
  readonly values: readonly unknown[];
  // 显式 JSON null 是否为合格取值（与“缺失”不同）
  readonly nullable: boolean;
  // 字段是否可缺省
  readonly optional: boolean;
}

// 在根对象规则与全部分支条件之上做精确的有限域可达性求解。
//
// 条件经多段对象字段指针形成一棵约束树；每个被引用的标量字段是一个维度，
// 取值域为 {缺失?，null?，各分支钉过的合格常量，一个合格其余值}。中间对象
// 字段按布局（缺失?/null?/存在）递归枚举；未被任何条件引用的字段、对象与
// 数组都不在维度中，而以 baseObject 的最小合格样本参与——后代必填只在父对象
// 存在且非 null 时才生效。该有限域对等值条件与首支命中精确（不是抽样）：
// 任意两个“其余值”对全部条件不可区分，未引用子树只影响合格性，最小样本与
// 任一布局的合格性恒等。
class ReachSolver {
  private readonly rootRule: Extract<BodyRule, { kind: 'object' }>;
  private readonly branches: readonly BranchSpec[];
  private readonly rootNode: ReachNode;
  private readonly dims: readonly ReachDim[];

  constructor(
    rootRule: Extract<BodyRule, { kind: 'object' }>,
    branches: readonly BranchSpec[],
  ) {
    this.rootRule = rootRule;
    this.branches = branches;
    this.rootNode = this.buildTree();
    this.dims = this.buildDims();
  }

  // 按全部条件建立对象约束树，并逐段校验字段链（范围预检已保证合法性，
  // 这里的字段查找只是构造数据结构）。
  private buildTree(): ReachNode {
    const root = new ReachNode(this.rootRule);
    const visit = (node: ReachNode, objectRule: Extract<BodyRule, { kind: 'object' }>): void => {
      for (const [name, field] of objectRule.fields) {
        if (field.required) {
          node.requiredNames.add(name);
        }
      }
    };
    visit(root, this.rootRule);

    for (const branch of this.branches) {
      for (const condition of branch.conditions) {
        let node = root;
        let objectRule = this.rootRule;
        for (let k = 0; k < condition.segments.length; k += 1) {
          const name = condition.segments[k];
          const field = objectRule.fields.get(name) as FieldRule;
          if (field.required) {
            node.requiredNames.add(name);
          }
          if (k === condition.segments.length - 1) {
            node.scalarFields.set(name, field.rule as Extract<BodyRule, { kind: ScalarKind }>);
          } else {
            let child = node.children.get(name);
            if (child === undefined) {
              child = new ReachNode(field.rule as Extract<BodyRule, { kind: 'object' }>);
              node.children.set(name, child);
            }
            node = child;
            objectRule = field.rule as Extract<BodyRule, { kind: 'object' }>;
          }
        }
      }
    }
    return root;
  }

  private buildDims(): ReachDim[] {
    // 维度首次被任何条件引用的顺序（按分支/条件配置顺序、深度展开）
    const order: Array<{ node: ReachNode; name: string }> = [];
    const seen = new Set<string>();
    const dimKey = (node: ReachNode, name: string): string =>
      `${this.depthOf(node)}\u0000${name}`;
    const referenced = new Map<ReachDim0, Set<unknown>>();

    for (const branch of this.branches) {
      for (const condition of branch.conditions) {
        const node = this.nodeOf(condition.segments);
        const name = condition.segments[condition.segments.length - 1];
        const key = dimKey(node, name);
        if (!seen.has(key)) {
          seen.add(key);
          order.push({ node, name });
        }
      }
    }

    return order.map(({ node, name }) => {
      const scalarRule = node.scalarFields.get(name) as Extract<BodyRule, { kind: ScalarKind }>;
      const field = node.objectRule.fields.get(name) as FieldRule;
      const ref = new Set<unknown>();
      const values: unknown[] = [];
      const pushed = new Set<unknown>();
      const push = (v: unknown): void => {
        if (!pushed.has(v)) {
          pushed.add(v);
          values.push(v);
          ref.add(v);
        }
      };
      // 各分支钉过且合格的常量
      for (const branch of this.branches) {
        for (const condition of branch.conditions) {
          const cNode = this.nodeOf(condition.segments);
          const cName = condition.segments[condition.segments.length - 1];
          if (cNode !== node || cName !== name) {
            continue;
          }
          if (scalarConditionConflict(scalarRule, condition.value) === null) {
            push(condition.value);
          }
        }
      }
      // 一个与全部钉值不同的合格其余值（无则省略，如枚举候选已被全部钉住）
      const rest = freshScalarValue(scalarRule, ref);
      if (rest !== undefined) {
        push(rest);
      }
      return {
        node,
        name,
        values,
        nullable: ruleAcceptsNullValue(scalarRule),
        optional: !field.required,
      };
    });
  }

  // 节点在约束树中的深度（根为 0）
  private depthOf(target: ReachNode): number {
    let depth = 0;
    const walk = (node: ReachNode, d: number): boolean => {
      if (node === target) {
        depth = d;
        return true;
      }
      for (const child of node.children.values()) {
        if (walk(child, d + 1)) {
          return true;
        }
      }
      return false;
    };
    walk(this.rootNode, 0);
    return depth;
  }

  private nodeOf(segments: readonly string[]): ReachNode {
    let node = this.rootNode;
    for (let k = 0; k < segments.length - 1; k += 1) {
      node = node.children.get(segments[k]) as ReachNode;
    }
    return node;
  }

  // 一支条件是否被正文全部满足：沿指针取值，取不到（祖先缺失、祖先为 null、
  // 在标量上深入、字段缺失）即不匹配；严格相等、不做类型转换。
  private satisfies(conditions: readonly BranchCondition[], value: unknown): boolean {
    for (const condition of conditions) {
      const actual = resolvePointer(value, condition.segments);
      if (actual === undefined || actual !== condition.value) {
        return false;
      }
    }
    return true;
  }

  private firstMatch(value: unknown): number | null {
    for (let i = 0; i < this.branches.length; i += 1) {
      if (this.satisfies(this.branches[i].conditions, value)) {
        return i;
      }
    }
    return null;
  }

  // 某节点对象的最小合格样本：含全部必填字段（含未引用的对象/数组/标量字段，
  // 递归取最小合格值）；字段名可能为 "" 或 "__proto__"，用无原型对象。
  private baseObject(node: ReachNode): Record<string, unknown> {
    const obj: Record<string, unknown> = Object.create(null);
    for (const [name, field] of node.objectRule.fields) {
      if (field.required) {
        obj[name] = sampleValue(field.rule);
      }
    }
    return obj;
  }

  // 钉值表：条件引用 -> 常量。
  private findObject(
    pins: ReadonlyMap<ReachConditionRef, BranchConditionValue>,
    predicate: (value: unknown) => boolean,
  ): Record<string, unknown> | typeof NO_WITNESS {
    // 每个约束节点的工作对象（节点 active 时挂到父对象对应字段上）
    const work = new Map<ReachNode, Record<string, unknown>>();
    work.set(this.rootNode, this.baseObject(this.rootNode));
    for (const child of this.allNodes(this.rootNode).slice(1)) {
      work.set(child, this.baseObject(child));
    }
    // 钉值写入对应叶字段（必然同时钉住其祖先链存在）
    for (const [ref, value] of pins) {
      const node = this.nodeOf(ref.segments);
      const name = ref.segments[ref.segments.length - 1];
      ;(work.get(node) as Record<string, unknown>)[name] = value;
    }

    // 中间对象节点（不含根）：深度从大到小枚举布局，父节点最后枚举。
    const innerNodes = this.allNodes(this.rootNode).slice(1);
    innerNodes.sort((a, b) => this.depthOf(b) - this.depthOf(a));
    const innerState = innerNodes.map(() => 0);
    // 每个中间节点的布局数：可缺失则多一个“缺失”布局；可空则多一个 null 布局。
    const innerLayouts = innerNodes.map((node) => {
      const name = this.childNameOf(node) as string;
      const parent = this.parentOf(node) as ReachNode;
      const field = parent.objectRule.fields.get(name) as FieldRule;
      return (field.required ? 0 : 1) + (ruleAcceptsNullValue(field.rule) ? 1 : 0) + 1;
    });

    // 标量维度：默认按 dims 顺序；active 仅当所在节点链全部“存在”。
    const dims = this.dims;

    // 判断中间节点当前是否处于“存在”布局（布局编号约定见 applyInner）
    const activeInner = new Set<ReachNode>();
    const root = this.rootNode;
    const rootObj = work.get(root) as Record<string, unknown>;

    const problems: StructureProblem[] = [];

    // 布局编号：0..（可选时 0=缺失），（可空时紧接 null），最后一个编号=存在。
    const existsLayout = (nodeIdx: number): number => innerLayouts[nodeIdx] - 1;
    const nullLayout = (nodeIdx: number): number | null => {
      const node = innerNodes[nodeIdx];
      const name = this.childNameOf(node) as string;
      const parent = this.parentOf(node) as ReachNode;
      const field = parent.objectRule.fields.get(name) as FieldRule;
      if (!ruleAcceptsNullValue(field.rule)) {
        return null;
      }
      return field.required ? 0 : 1;
    };

    const applyInner = (nodeIdx: number): void => {
      const node = innerNodes[nodeIdx];
      const name = this.childNameOf(node) as string;
      const parent = this.parentOf(node) as ReachNode;
      const parentObj = work.get(parent) as Record<string, unknown>;
      const layout = innerState[nodeIdx];
      const nullLayoutIdx = nullLayout(nodeIdx);
      if (layout === existsLayout(nodeIdx)) {
        parentObj[name] = work.get(node) as Record<string, unknown>;
        activeInner.add(node);
      } else if (nullLayoutIdx !== null && layout === nullLayoutIdx) {
        parentObj[name] = null;
        activeInner.delete(node);
      } else {
        delete parentObj[name];
        activeInner.delete(node);
      }
    };

    const chainActive = (node: ReachNode): boolean => {
      let cur: ReachNode | undefined = node;
      while (cur !== root && cur !== undefined) {
        if (!activeInner.has(cur)) {
          return false;
        }
        cur = this.parentOf(cur);
      }
      return true;
    };

    // 某维度是否被钉值固定（钉住时跳过其域枚举）
    const pinnedDim = (dim: ReachDim): BranchConditionValue | undefined => {
      for (const [ref, value] of pins) {
        if (this.nodeOf(ref.segments) === dim.node &&
          ref.segments[ref.segments.length - 1] === dim.name) {
          return value;
        }
      }
      return undefined;
    };

    const dimState = dims.map(() => 0);
    // 每维状态数：0=缺失（可选时），随后 null（可空时），再依次 values。
    const dimSize = (dim: ReachDim): number =>
      (dim.optional ? 1 : 0) + (dim.nullable ? 1 : 0) + dim.values.length;
    const dimMissing = (dim: ReachDim): number => (dim.optional ? 0 : -1);
    const dimNullIdx = (dim: ReachDim): number => (dim.nullable ? (dim.optional ? 1 : 0) : -1);
    const dimValueOffset = (dim: ReachDim): number =>
      (dim.optional ? 1 : 0) + (dim.nullable ? 1 : 0);

    const applyDim = (dimIdx: number): void => {
      const dim = dims[dimIdx];
      const obj = work.get(dim.node) as Record<string, unknown>;
      const state = dimState[dimIdx];
      const miss = dimMissing(dim);
      const nullIdx = dimNullIdx(dim);
      if (state === miss) {
        delete obj[dim.name];
      } else if (state === nullIdx) {
        obj[dim.name] = null;
      } else {
        obj[dim.name] = dim.values[state - dimValueOffset(dim)];
      }
    };

    const check = (): Record<string, unknown> | typeof NO_WITNESS => {
      problems.length = 0;
      checkRule(this.rootRule, rootObj, '', problems);
      if (problems.length === 0 && predicate(rootObj)) {
        return rootObj;
      }
      return NO_WITNESS;
    };

    // 先摆好全部中间节点布局，再递归枚举标量维度。
    for (let i = 0; i < innerNodes.length; i += 1) {
      applyInner(i);
    }

    const enumDims = (dimIdx: number): Record<string, unknown> | typeof NO_WITNESS => {
      if (dimIdx === dims.length) {
        return check();
      }
      const dim = dims[dimIdx];
      const pinned = pinnedDim(dim);
      if (pinned !== undefined) {
        // 钉值只在祖先链存在时生效；祖先缺失/null 的布局下该维不存在，
        // checkRule 不会因钉值报错（字段缺省），但谓词（首支命中）会排除它。
        if (chainActive(dim.node)) {
          const obj = work.get(dim.node) as Record<string, unknown>;
          obj[dim.name] = pinned;
        }
        const found = enumDims(dimIdx + 1);
        if (found !== NO_WITNESS) {
          return found;
        }
        return NO_WITNESS;
      }
      for (let state = 0; state < dimSize(dim); state += 1) {
        dimState[dimIdx] = state;
        // 祖先链不“存在”时该维取值无意义：只尝试一种状态即可
        if (!chainActive(dim.node)) {
          return enumDims(dimIdx + 1);
        }
        applyDim(dimIdx);
        const found = enumDims(dimIdx + 1);
        if (found !== NO_WITNESS) {
          return found;
        }
      }
      return NO_WITNESS;
    };

    const enumInner = (nodeIdx: number): Record<string, unknown> | typeof NO_WITNESS => {
      if (nodeIdx === innerNodes.length) {
        return enumDims(0);
      }
      // 钉值涉及的节点链必须取“存在”布局：直接定位到存在布局
      const node = innerNodes[nodeIdx];
      const forcedExists = this.nodePinned(node, pins);
      for (let layout = 0; layout < innerLayouts[nodeIdx]; layout += 1) {
        if (forcedExists && layout !== existsLayout(nodeIdx)) {
          continue;
        }
        innerState[nodeIdx] = layout;
        applyInner(nodeIdx);
        const found = enumInner(nodeIdx + 1);
        if (found !== NO_WITNESS) {
          return found;
        }
      }
      return NO_WITNESS;
    };

    return enumInner(0);
  }

  // 该节点自身或其后代是否被钉值（钉值要求整条祖先链存在）
  private nodePinned(
    node: ReachNode,
    pins: ReadonlyMap<ReachConditionRef, BranchConditionValue>,
  ): boolean {
    for (const ref of pins.keys()) {
      let cur = this.rootNode;
      for (let k = 0; k < ref.segments.length - 1; k += 1) {
        cur = cur.children.get(ref.segments[k]) as ReachNode;
        if (cur === node) {
          return true;
        }
      }
    }
    return false;
  }

  private allNodes(node: ReachNode): ReachNode[] {
    const out = [node];
    for (const child of node.children.values()) {
      out.push(...this.allNodes(child));
    }
    return out;
  }

  private parentOf(target: ReachNode): ReachNode | undefined {
    const walk = (node: ReachNode): ReachNode | undefined => {
      for (const child of node.children.values()) {
        if (child === target) {
          return node;
        }
        const found = walk(child);
        if (found !== undefined) {
          return found;
        }
      }
      return undefined;
    };
    return walk(this.rootNode);
  }

  private childNameOf(target: ReachNode): string | undefined {
    const parent = this.parentOf(target);
    if (parent === undefined) {
      return undefined;
    }
    for (const [name, child] of parent.children) {
      if (child === target) {
        return name;
      }
    }
    return undefined;
  }

  // 找一份合格正文：根可空且无钉值时先尝试 JSON null（任何字段指针在 null 上
  // 都取不到值、不命中分支），再在对象域上求解；有钉值时只能是对象正文。
  findWitness(
    pins: ReadonlyMap<ReachConditionRef, BranchConditionValue>,
    predicate: (value: unknown) => boolean,
  ): Witness {
    if (pins.size === 0 && ruleAcceptsNullValue(this.rootRule)) {
      if (predicate(null)) {
        return null;
      }
    }
    return this.findObject(pins, predicate);
  }

  // 两支钉值是否相容：同一条件引用（同指针）常量严格相等才算共同正文可行。
  // 不同指针的钉值恒相容（含共享祖先下的兄弟字段与不同祖先下的字段）。
  private mergePins(
    a: ReadonlyMap<ReachConditionRef, BranchConditionValue>,
    b: ReadonlyMap<ReachConditionRef, BranchConditionValue>,
  ): Map<ReachConditionRef, BranchConditionValue> | null {
    const merged = new Map(a);
    for (const [ref, value] of b) {
      const existing = merged.get(ref);
      if (existing !== undefined && existing !== value) {
        return null;
      }
      merged.set(ref, value);
    }
    return merged;
  }

  private example(value: unknown, routePath: string): ReachExample {
    return {
      method: 'POST',
      path: routePath,
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(value),
    };
  }

  solve(routePath: string): { branches: BranchReach[]; fallback: FallbackReach } {
    const analyses = this.branches.map((branch) => analyzeBranchConditions(branch, this.rootNode));

    const branchResults: BranchReach[] = [];
    for (let i = 0; i < this.branches.length; i += 1) {
      const branch = this.branches[i];
      const analysis = analyses[i];
      if (!analysis.ok || analysis.pins === undefined) {
        branchResults.push({ id: branch.id, status: 'contradictory', reasons: analysis.reasons });
        continue;
      }

      // 存在合格正文首先命中此支？
      const direct = this.findWitness(analysis.pins, (value) => this.firstMatch(value) === i);
      if (direct !== NO_WITNESS) {
        branchResults.push({ id: branch.id, status: 'reachable', example: this.example(direct, routePath) });
        continue;
      }

      // 满足此支的合格正文必然首先命中某些前序分支——逐支给出共同遮挡者
      const coveredBy: string[] = [];
      for (let j = 0; j < i; j += 1) {
        const prior = analyses[j];
        if (!prior.ok || prior.pins === undefined) {
          continue;
        }
        const merged = this.mergePins(analysis.pins, prior.pins);
        if (merged === null) {
          continue;
        }
        // 同时满足 i 与 j、且首支命中恰为 j 的合格正文
        const witness = this.findWitness(merged, (value) => this.firstMatch(value) === j);
        if (witness !== NO_WITNESS) {
          coveredBy.push(this.branches[j].id);
        }
      }
      branchResults.push({
        id: branch.id,
        status: 'covered',
        coveredBy,
        message:
          `存在满足本支全部条件的合格正文，但它们首先命中的都是前序分支；` +
          `前序分支 ${JSON.stringify(coveredBy)} 的命中区域并集已覆盖本支，本支永远不会被首先选中`,
      });
    }

    // 兜底：存在任何分支都不命中的合格正文（含根为 JSON null）即可达
    const fallbackBody = this.findWitness(new Map(), (value) => this.firstMatch(value) === null);
    let fallback: FallbackReach;
    if (fallbackBody !== NO_WITNESS) {
      fallback = { status: 'reachable', example: this.example(fallbackBody, routePath) };
    } else {
      const noWitness = NO_WITNESS;
      const coveredBy = this.branches
        .map((branch, j) => {
          const analysis = analyses[j];
          if (!analysis.ok || analysis.pins === undefined) {
            return noWitness;
          }
          const witness = this.findWitness(analysis.pins, (value) => this.firstMatch(value) === j);
          return witness !== noWitness ? branch.id : noWitness;
        })
        .filter((id): id is string => id !== noWitness);
      fallback = {
        status: 'covered',
        coveredBy,
        message:
          `没有任何合格正文落到兜底：全部合格正文都被分支 ${JSON.stringify(coveredBy)} 的命中区域并集覆盖`,
      };
    }

    return { branches: branchResults, fallback };
  }
}

